public int findAthFibonacci(int A) {
    if (A == 0) {
        return 0;
    }
    if (A == 1) {
        return 1;
    }
    return findAthFibonacci(A - 1) + findAthFibonacci(A - 2);
}

public int fibIter(int A) {
    if (A == 0) {
        return 0;
    }
    int a = 0;
    int b = 1;
    for (int i = 2; i <= A; i++) {
        int c = a + b;
        a = b;
        b = c;
    }
    return b;
}

