public int solve(String A) {
    char[] arr = A.toCharArray();
    return isPali(arr, 0, arr.length - 1) ? 1 : 0;
}

private boolean isPali(char[] arr, int start, int end) {
    if (start >= end) {
        return true;
    }
    if (arr[start] != arr[end]) {
        return false;
    }
    return isPali(arr, start + 1, end - 1);
}

public java.util.ArrayList<java.util.ArrayList<Integer>> towerOfHanoi(int A) {
    java.util.ArrayList<java.util.ArrayList<Integer>> result = new java.util.ArrayList<>();
    hanoi(A, 1, 2, 3, result);
    return result;
}

private void hanoi(int n, int source, int helper, int destination,
                   java.util.ArrayList<java.util.ArrayList<Integer>> result) {
    if (n == 0) {
        return;
    }
    hanoi(n - 1, source, destination, helper, result);
    java.util.ArrayList<Integer> move = new java.util.ArrayList<>();
    move.add(n);
    move.add(source);
    move.add(destination);
    result.add(move);
    hanoi(n - 1, helper, source, destination, result);
}

public int[] allIndices(int[] A, int B) {
    java.util.ArrayList<Integer> ar = collect(A, A.length, B);
    int[] result = new int[ar.size()];
    for (int i = 0; i < ar.size(); i++) {
        result[i] = ar.get(i);
    }
    return result;
}

private java.util.ArrayList<Integer> collect(int[] A, int N, int B) {
    if (N == 0) {
        return new java.util.ArrayList<>();
    }
    java.util.ArrayList<Integer> list = collect(A, N - 1, B);
    if (A[N - 1] == B) {
        list.add(N - 1);
    }
    return list;
}

