private void printRec(int[] A, int N) {
    if (N == 0) {
        return;
    }
    printRec(A, N - 1);
    System.out.print(A[N - 1] + " ");
}

public long powerBrute(int A, int B) {
    long result = 1;
    for (int i = 0; i < B; i++) {
        result *= A;
    }
    return result;
}

public long power(int A, int B) {
    if (B == 1) {
        return A;
    }
    long halfPower = power(A, B / 2);
    if (B % 2 == 0) {
        return halfPower * halfPower;
    } else {
        return halfPower * halfPower * A;
    }
}

public int FirstIndex(int[] A, int B) {
    return firstIdx(A, B, 0);
}

private int firstIdx(int[] A, int B, int idx) {
    if (idx == A.length) {
        return -1;
    }
    if (A[idx] == B) {
        return idx;
    }
    return firstIdx(A, B, idx + 1);
}

public int LastIndex(int[] A, int B) {
    return lastIdx(A, B, 0);
}

private int lastIdx(int[] A, int B, int idx) {
    if (idx == A.length) {
        return -1;
    }
    int rest = lastIdx(A, B, idx + 1);
    if (rest != -1) {
        return rest;
    }
    if (A[idx] == B) {
        return idx;
    }
    return -1;
}
